import json
import os
import re
import numpy as np
import logging

logger = logging.getLogger(__name__)

from .utils import format_str, find_func_in_module
from .utils import get_func_inputs_outputs_with_attrs, get_clostest_pow2, np_supported_types

header = """
//=============================================================================
// Auto generated by ST-Flow
//=============================================================================

// OpenCL utility layer include
#include "xcl2.hpp"
#include <algorithm>
#include <cstdio>
#include <cmath>
#include <random>
#include <vector>
#include <iomanip>
#include <fstream>
"""

main_header = """
int main(int argc, char** argv) {
    if (argc != 2) {
        std::cout << "Usage: " << argv[0] << " <XCLBIN File>" << std::endl;
        return EXIT_FAILURE;
    }

    std::string binaryFile = argv[1];
    cl_int err;
    cl::CommandQueue q;
    cl::Context context;
    cl::Program program;
"""

dtype_size_map = {
    "int8": 1,
    "int16": 2,
    "int32": 4,
    "int64": 8,
    "uint8": 1,
    "uint16": 2,
    "uint32": 4,
    "uint64": 8,
    "float16": 2,
    "float32": 4,
    "float64": 8,
}

ctype_map = {
    "bf16": "std::bfloat16_t",
    "f32": "float",
    "f64": "double",
    "i8": "int8_t",
    "i16": "short",
    "i32": "int",
    "i64": "long",
    "i128": "__int128_t",  # unverified
    "ui1": "bool",
    "ui8": "uint8_t",
    "ui16": "unsigned short",
    "ui32": "unsigned int",
    "ui64": "unsigned long",
}


# print(inputs, outputs)
# print(func.arguments)
# for named_attr in func.attributes:
#     if named_attr.name == "arg_attrs":
#         for i, arg_attr in enumerate(named_attr.attr):
#             print(f"arg {i} attrs: {arg_attr}")
# return ''
# print(func.attributes)
# for attr in func.attributes:
#     print(attr)
# # Option 1: inspect all attributes
# for named_attr in func.attributes:
#     print("top-level name:", named_attr.name)
#     if named_attr.name == "arg_attrs":
#         for i, arg_attr in enumerate(named_attr.attr):
#             print(f"arg {i} attrs: {arg_attr}")
#     print("top-level attr:", named_attr.attr)
# Get input/output types
def codegen_host(top, module):
    # Reference: https://github.com/Xilinx/Vitis_Accel_Examples/blob/main/sys_opt/kernel_swap/src/host.cpp
    # Try to find "module_top" first
    func = find_func_in_module(module, "module_top")
    if func is not None:
        top = "module_top"
    else:
        func = find_func_in_module(module, top)
    
    if func is None:
        # Provide a clearer error message earlier with module context to aid debugging
        try:
            mod_text = str(module)
        except Exception:
            mod_text = "<unable to stringify module>"
        raise RuntimeError(f"Function '{top}' not found in module. Module: {mod_text}")
    inputs, outputs, inputs_outputs = get_func_inputs_outputs_with_attrs(func)
    logger.info("Inputs: %s, Outputs: %s, InputsOutputs: %s", inputs, outputs, inputs_outputs)
    
    # Build a mapping to preserve original argument order
    # We need to know which argument is which type (input/output/input_output) and in what order
    arg_attrs = None
    for attr_p in func.attributes:
        if attr_p.name == "arg_attrs":
            arg_attrs = attr_p.attr
    
    # Create ordered list of all arguments with their types
    ordered_args = []  # List of (arg_index, arg_type, arg_data) where arg_type is 'input', 'output', or 'input_output'
    input_idx = 0
    output_idx = 0
    input_output_idx = 0
    
    for i, (arg, arg_attr) in enumerate(zip(func.arguments, arg_attrs)):
        buf_info = arg_attr['buffer.info']
        io = buf_info['io'].value
        if io == 'read-only':
            ordered_args.append(('input', input_idx, inputs[input_idx]))
            input_idx += 1
        elif io == 'write-only':
            ordered_args.append(('output', output_idx, outputs[output_idx]))
            output_idx += 1
        elif io == 'read-write' or io == 'unknown':
            ordered_args.append(('input_output', input_output_idx, inputs_outputs[input_output_idx]))
            input_output_idx += 1
    out_str = format_str(header, indent=0, strip=False)

    # Auto-detect a generated golden header and include it when present.
    # This makes host generation generally add the golden comparator when
    # `golden.h` is available in the project `src/` or current directory.
    golden_paths = ["golden.h", os.path.join("src", "golden.h")]
    golden_found = any(os.path.exists(p) for p in golden_paths)
    if golden_found:
        pass
        # out_str += format_str('#include "golden.h"\n', strip=False)

    # Auto-detect a compiled golden reference implementation and prepare to
    # call it from the host if present (e.g. `src/golden_reference.cpp`).
    # If found, we'll declare an extern prototype and call it at runtime to
    # produce a host-side reference output for comparison.
    golden_ref_paths = ["golden_reference.cpp", os.path.join("src", "golden_reference.cpp")]
    golden_ref_found = any(os.path.exists(p) for p in golden_ref_paths)

    # If a golden reference implementation is present, declare its symbol
    # at global scope (before `main`) so the declaration is not emitted
    # inside the `main` function body which can lead to compiler errors.
    if golden_ref_found:
        # Prefer to reuse the exact prototype declared in the generated
        # `golden_reference.cpp` wrapper. If present, parse and re-use it.
        proto_with_names = None
        for p in golden_ref_paths:
            if os.path.exists(p):
                try:
                    with open(p, "r", encoding="utf-8") as gf:
                        text = gf.read()
                    m = re.search(r'extern\s+"C"\s+void\s+top_golden\s*\((.*?)\)\s*{', text, re.S)
                    if m:
                        proto_with_names = m.group(1).strip()
                        break
                except Exception:
                    proto_with_names = None
        if proto_with_names is not None and proto_with_names == "":
            proto_with_names = "void"
        if proto_with_names is None:
            # Fallback: build a C prototype matching the kernel argument list
            proto_params = []
            for arg_type, idx, arg_data in ordered_args:
                dtype, shape, name, kind = arg_data
                if dtype in ctype_map:
                    ctype = ctype_map[dtype]
                elif dtype.startswith("i") or dtype.startswith("ui"):
                    prefix, bitwidth = dtype.split("i")
                    new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
                    ctype = ctype_map[new_int_type]
                elif dtype.startswith("fixed") or dtype.startswith("ufixed"):
                    ctype = "float"
                else:
                    raise ValueError(f"Unsupported input type: {dtype}")
                if len(shape) == 0:
                    proto_params.append(ctype)
                else:
                    proto_params.append(f"{ctype}*")
            proto_with_names = ", ".join([f"{t} arg{idx}" for idx, t in enumerate(proto_params)]) if proto_params else "void"
        out_str += format_str(f'extern "C" void top_golden({proto_with_names});\n', strip=False)

        # Also emit a file-scope extern for the kernel `top` so the host
        # can reference the unmangled symbol if needed by the runtime
        # (e.g., certain emulation/linking setups expect a C symbol).
        # Build a prototype for `top` from the ordered argument list.
        top_proto_params = []
        for arg_position, (arg_type, idx, arg_data) in enumerate(ordered_args):
            dtype, shape, name, kind = arg_data
            if dtype in ctype_map:
                ctype = ctype_map[dtype]
            elif dtype.startswith("i") or dtype.startswith("ui"):
                prefix, bitwidth = dtype.split("i")
                new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
                ctype = ctype_map[new_int_type]
            elif dtype.startswith("fixed") or dtype.startswith("ufixed"):
                ctype = "float"
            else:
                raise ValueError(f"Unsupported input type: {dtype}")
            if len(shape) == 0:
                top_proto_params.append(ctype)
            else:
                top_proto_params.append(f"{ctype}*")
        top_proto_with_names = ", ".join([f"{t} arg{p}" for p, t in enumerate(top_proto_params)]) if top_proto_params else "void"
        out_str += format_str(f'extern "C" void {top}({top_proto_with_names});\n', strip=False)
    out_str += format_str(main_header, indent=0, strip=False)
    out_str += format_str("cl::Kernel krnl_" + top + ";\n", strip=False)
    out_str += format_str(
        """
        // Allocate Memory in Host Memory
        // When creating a buffer with user pointer (CL_MEM_USE_HOST_PTR), under the
        // hood user ptr is used if it is properly aligned. when not aligned, runtime had no choice
        // but to create its own host side buffer. So it is recommended to use this allocator if
        // user wish to create buffer using CL_MEM_USE_HOST_PTR to align user buffer to page
        // boundary. It will ensure that user buffer is used when user create Buffer/Mem object with
        // CL_MEM_USE_HOST_PTR
        """
    )
    # Generate in/out buffers
    for i, (in_dtype, in_shape, in_name, in_kind) in enumerate(inputs):
        if in_dtype in ctype_map:
            in_dtype = ctype_map[in_dtype]
        elif in_dtype.startswith("i") or in_dtype.startswith("ui"):
            prefix, bitwidth = in_dtype.split("i")
            if int(bitwidth) == 1:
                in_dtype = "bool"
            else:
                new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
                in_dtype = ctype_map[new_int_type]
        elif in_dtype.startswith("fixed") or in_dtype.startswith("ufixed"):
            in_dtype = "float"
        else:
            raise ValueError(f"Unsupported input type: {in_dtype}")
        if in_kind == "weights":
            out_str += format_str(f'std::ifstream ifile{i}("../../weight_bins/{in_name}.bin");')
            out_str += format_str(f"if (!ifile{i}.is_open()) {{")
            out_str += format_str(
                '  std::cerr << "Error: Could not open weight file.\\n";', strip=False
            )
            out_str += format_str("  return 1;", strip=False)
            out_str += format_str("}")
        else:
            out_str += format_str(f'std::ifstream ifile{i}("input{i}.data");')

        in_shape = [str(i) for i in in_shape]
        if len(in_shape) == 0:
            # scalar
            out_str += format_str(f"{in_dtype} source_in{i};")
            out_str += format_str(f"if (ifile{i}.is_open()) {{")
            out_str += format_str(f"  ifile{i} >> source_in{i};", strip=False)
            out_str += format_str("} else {")
            out_str += format_str(f'  std::cout << "Warning: input{i}.data not found. Creating dummy input file..." << std::endl;', strip=False)
            out_str += format_str(f'  std::ofstream ofile{i}("input{i}.data");')
            out_str += format_str(f'  std::random_device rd{i}; std::mt19937 gen{i}(rd{i}());')
            if in_dtype in ("float", "double", "std::bfloat16_t"):
                out_str += format_str(f'  std::uniform_real_distribution<{in_dtype}> dist{i}(0.0, 1.0);')
            else:
                out_str += format_str(f'  std::uniform_int_distribution<long> dist{i}(0, 1000);')
            out_str += format_str(f"  source_in{i} = ({in_dtype})dist{i}(gen{i});", strip=False)
            out_str += format_str(f"  ofile{i} << source_in{i} << std::endl;")
            out_str += format_str(f"  ofile{i}.close();")
            out_str += format_str("}")
        else:
            out_str += format_str(
                f"{in_dtype} in_data_{i}[{'*'.join(map(str, in_shape))}];"
            )
            out_str += format_str(f"if (ifile{i}.is_open()) {{")
            out_str += format_str(
                f"  for (unsigned __idx = 0; __idx < {'*'.join(map(str, in_shape))}; ++__idx) {{",
                strip=False,
            )
            out_str += format_str(f"    ifile{i} >> in_data_{i}[__idx];", strip=False)
            out_str += format_str("  }")
            out_str += format_str("} else {")
            out_str += format_str(f'  std::cout << "Warning: input{i}.data not found. Creating dummy input file..." << std::endl;', strip=False)
            out_str += format_str(f'  std::ofstream ofile{i}("input{i}.data");')
            out_str += format_str(f'  std::random_device rd{i}; std::mt19937 gen{i}(rd{i}());')
            if in_dtype in ("float", "double", "std::bfloat16_t"):
                out_str += format_str(f'  std::uniform_real_distribution<{in_dtype}> dist{i}(0.0, 1.0);')
            else:
                out_str += format_str(f'  std::uniform_int_distribution<long> dist{i}(0, 1000);')
            out_str += format_str(
                f"  for (unsigned __idx = 0; __idx < {'*'.join(map(str, in_shape))}; ++__idx) {{",
                strip=False,
            )
            out_str += format_str(f"    auto __v = ({in_dtype})dist{i}(gen{i});", strip=False)
            out_str += format_str(f"    in_data_{i}[__idx] = __v;", strip=False)
            out_str += format_str(f"    ofile{i} << __v << std::endl;", strip=False)
            out_str += format_str("  }")
            out_str += format_str(f"  ofile{i}.close();")
            out_str += format_str("}")
            out_str += format_str(
                f"size_t size_bytes_in{i} = sizeof({in_dtype}) * {' * '.join(in_shape)};",
                strip=False,
            )
            out_str += format_str(
                f"std::vector<{in_dtype}, aligned_allocator<{in_dtype}> > source_in{i}(in_data_{i}, in_data_{i} + {' * '.join(in_shape)});",
                strip=False,
            )
    # Generate buffers for inputs_outputs (read-write buffers, including sync buffers)
    # Use indices starting from 0 for inputs_outputs
    for io_idx, (io_type, io_shape, io_name, io_kind) in enumerate(inputs_outputs):
        if io_type in ctype_map:
            io_type = ctype_map[io_type]
        elif io_type.startswith("i") or io_type.startswith("ui"):
            prefix, bitwidth = io_type.split("i")
            new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
            io_type = ctype_map[new_int_type]
        elif io_type.startswith("fixed") or io_type.startswith("ufixed"):
            io_type = "float"
        else:
            raise ValueError(f"Unsupported input type: {io_type}")
        # Filter out invalid shapes (negative or zero values, or very large negative numbers)
        valid_shape = []
        for dim in io_shape:
            if isinstance(dim, str):
                valid_shape.append(str(dim))
            elif isinstance(dim, int) and dim > 0:
                valid_shape.append(str(dim))
        if not valid_shape:
            # Skip if shape is invalid
            continue
        
        # Check if this is a sync buffer (buffers created for sync operations)
        # Sync buffers are typically named with patterns like "buf" followed by numbers
        is_sync_buffer = "buf" in io_name.lower() or "sync" in io_name.lower()
        
        out_str += format_str(
            f"size_t size_bytes_out{io_idx} = sizeof({io_type}) * {' * '.join(valid_shape)};\n",
            strip=False,
        )
        
        # For sync buffers, try to initialize from file if it exists, otherwise use zeros
        if is_sync_buffer:
            # Try to read from input file for sync buffer, fallback to zeros
            out_str += format_str(
                f"std::vector<{io_type}, aligned_allocator<{io_type}> > source_out{io_idx}({' * '.join(valid_shape)});\n",
                strip=False,
            )
            out_str += format_str(
                f"std::fill(source_out{io_idx}.begin(), source_out{io_idx}.end(), 0);\n", strip=False
            )
            out_str += format_str(
                f'std::ifstream sync_file{io_idx}("sync_{io_name}.data");\n',
                strip=False,
            )
            out_str += format_str(
                f"if (sync_file{io_idx}.is_open()) {{\n",
                strip=False,
            )
            out_str += format_str(
                f"  for (unsigned i = 0; i < {' * '.join(valid_shape)}; i++) {{\n",
                strip=False,
            )
            out_str += format_str(
                f"    sync_file{io_idx} >> source_out{io_idx}[i];\n",
                strip=False,
            )
            out_str += format_str(
                f"  }}\n",
                strip=False,
            )
            out_str += format_str(
                f"  sync_file{io_idx}.close();\n",
                strip=False,
            )
            out_str += format_str(
                f"}}\n",
                strip=False,
            )
        else:
            # Regular input_output buffer - initialize with zeros
            out_str += format_str(
                f"std::vector<{io_type}, aligned_allocator<{io_type}> > source_out{io_idx}({' * '.join(valid_shape)});\n",
                strip=False,
            )
            out_str += format_str(
                f"std::fill(source_out{io_idx}.begin(), source_out{io_idx}.end(), 0);\n", strip=False
            )
    out_str += "\n"
    # Generate buffers for outputs (write-only buffers)
    # Use indices starting after inputs_outputs to avoid conflicts
    for out_idx, (out_dtype, out_shape, out_name, out_kind) in enumerate(outputs):
        if out_dtype in ctype_map:
            out_dtype = ctype_map[out_dtype]
        elif out_dtype.startswith("i") or out_dtype.startswith("ui"):
            prefix, bitwidth = out_dtype.split("i")
            new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
            out_dtype = ctype_map[new_int_type]
        elif out_dtype.startswith("fixed") or out_dtype.startswith("ufixed"):
            out_dtype = "float"
        else:
            raise ValueError(f"Unsupported input type: {out_dtype}")
        # Filter out invalid shapes (negative or zero values, or very large negative numbers)
        valid_shape = []
        for dim in out_shape:
            if isinstance(dim, str):
                valid_shape.append(str(dim))
            elif isinstance(dim, int) and dim > 0:
                valid_shape.append(str(dim))
        if not valid_shape:
            # Skip if shape is invalid
            continue
        # Use index starting after inputs_outputs to avoid conflicts
        final_idx = len(inputs_outputs) + out_idx
        out_str += format_str(
            f"size_t size_bytes_out{final_idx} = sizeof({out_dtype}) * {' * '.join(valid_shape)};\n",
            strip=False,
        )
        out_str += format_str(
            f"std::vector<{out_dtype}, aligned_allocator<{out_dtype}> > source_out{final_idx}({' * '.join(valid_shape)});\n",
            strip=False,
        )
        out_str += format_str(
            f"std::fill(source_out{final_idx}.begin(), source_out{final_idx}.end(), 0);\n", strip=False
        )
    out_str += "\n"
    # If we have a golden reference implementation, allocate matching host
    # buffers for the golden run, call the golden function on the host with
    # the same argument layout, and keep the golden outputs for later
    # comparison with kernel outputs.
    if golden_ref_found:
        golden_creation = []
        golden_call_args = []
        input_idx = 0
        output_idx = 0
        input_output_idx = 0
        golden_out_counter = 0

        for arg_type, idx, arg_data in ordered_args:
            dtype, shape, name, kind = arg_data
            # map to ctype
            if dtype in ctype_map:
                ctype = ctype_map[dtype]
            elif dtype.startswith("i") or dtype.startswith("ui"):
                prefix, bitwidth = dtype.split("i")
                new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
                ctype = ctype_map[new_int_type]
            elif dtype.startswith("fixed") or dtype.startswith("ufixed"):
                ctype = "float"
            else:
                raise ValueError(f"Unsupported input type: {dtype}")

            if arg_type == 'input':
                # For inputs, create golden C-arrays for 2D shapes so the
                # reference (which often expects e.g. float A[H][W]) can be
                # called directly with them. For 1D or scalar inputs reuse
                # existing host buffers.
                if len(shape) == 0:
                    # scalar: wrapper expects a pointer to scalar
                    golden_call_args.append(f"&source_in{input_idx}")
                elif len(shape) == 1:
                    golden_call_args.append(f"source_in{input_idx}.data()")
                elif len(shape) == 2:
                    r, c = shape
                    # declare 2D C-array and fill from flat source_in vector
                    golden_creation.append(f"{ctype} golden_in{input_idx}[{r}][{c}];")
                    golden_creation.append(
                        f"for (unsigned __i = 0; __i < {r}; ++__i) for (unsigned __j = 0; __j < {c}; ++__j) golden_in{input_idx}[__i][__j] = source_in{input_idx}[__i*{c} + __j];"
                    )
                    # pass pointer to first element of the C 2D array
                    golden_call_args.append(f"&golden_in{input_idx}[0][0]")
                else:
                    # higher ranks: fall back to pointer to flat data
                    golden_call_args.append(f"source_in{input_idx}.data()")
                input_idx += 1

            elif arg_type == 'output':
                # Create golden output storage matching the expected shape.
                if len(shape) == 0:
                    golden_creation.append(f"{ctype} golden_out{golden_out_counter};")
                    golden_call_args.append(f"&golden_out{golden_out_counter}")
                elif len(shape) == 1:
                    golden_creation.append(f"std::vector<{ctype}, aligned_allocator<{ctype}> > golden_out{golden_out_counter}({' * '.join(map(str, shape))});")
                    golden_creation.append(f"std::fill(golden_out{golden_out_counter}.begin(), golden_out{golden_out_counter}.end(), 0);")
                    golden_call_args.append(f"golden_out{golden_out_counter}.data()")
                elif len(shape) == 2:
                    r, c = shape
                    golden_creation.append(f"{ctype} golden_out{golden_out_counter}[{r}][{c}];")
                    golden_creation.append(f"for (unsigned __i = 0; __i < {r}; ++__i) for (unsigned __j = 0; __j < {c}; ++__j) golden_out{golden_out_counter}[__i][__j] = 0;")
                    # pass pointer to first element of the C 2D array
                    golden_call_args.append(f"&golden_out{golden_out_counter}[0][0]")
                else:
                    golden_creation.append(f"std::vector<{ctype}, aligned_allocator<{ctype}> > golden_out{golden_out_counter}({' * '.join(map(str, shape))});")
                    golden_creation.append(f"std::fill(golden_out{golden_out_counter}.begin(), golden_out{golden_out_counter}.end(), 0);")
                    golden_call_args.append(f"golden_out{golden_out_counter}.data()")
                output_idx += 1
                golden_out_counter += 1

            elif arg_type == 'input_output':
                # Allocate golden storage for input_output buffers and copy
                # the current host sync data into it for the reference run.
                continue # FIXME BUT for now we just ignore because it correspond to temporary array that we use for memory coherency
                if len(shape) == 0:
                    golden_creation.append(f"{ctype} golden_io{golden_out_counter};")
                    golden_creation.append(f"golden_io{golden_out_counter} = source_out{input_output_idx};")
                    golden_call_args.append(f"&golden_io{golden_out_counter}")
                elif len(shape) == 1:
                    golden_creation.append(f"std::vector<{ctype}, aligned_allocator<{ctype}> > golden_io{golden_out_counter}(source_out{input_output_idx}.begin(), source_out{input_output_idx}.end());")
                    golden_call_args.append(f"golden_io{golden_out_counter}.data()")
                elif len(shape) == 2:
                    r, c = shape
                    golden_creation.append(f"{ctype} golden_io{golden_out_counter}[{r}][{c}];")
                    golden_creation.append(
                        f"for (unsigned __i = 0; __i < {r}; ++__i) for (unsigned __j = 0; __j < {c}; ++__j) golden_io{golden_out_counter}[__i][__j] = source_out{input_output_idx}[__i*{c} + __j];"
                    )
                    # pass pointer to first element of the C 2D array
                    golden_call_args.append(f"&golden_io{golden_out_counter}[0][0]")
                else:
                    golden_creation.append(f"std::vector<{ctype}, aligned_allocator<{ctype}> > golden_io{golden_out_counter}(source_out{input_output_idx}.begin(), source_out{input_output_idx}.end());")
                    golden_call_args.append(f"golden_io{golden_out_counter}.data()")
                input_output_idx += 1
                golden_out_counter += 1

        # Emit golden buffer declarations and the call to the golden reference
        if golden_creation:
            out_str += "\n"
            for line in golden_creation:
                out_str += format_str(line, strip=False)
        out_str += format_str("// Run golden reference on host", strip=False)
        out_str += format_str(f"top_golden({', '.join(golden_call_args)});", strip=False)
        out_str += "\n"

    # Generate OpenCL host code
    out_str += format_str(
        """
        // OPENCL HOST CODE AREA START
        // get_xil_devices() is a utility API which will find the xilinx
        // platforms and will return list of devices connected to Xilinx platform
        auto devices = xcl::get_xil_devices();
        // read_binary_file() is a utility API which will load the binaryFile
        // and will return the pointer to file buffer.
        auto fileBuf = xcl::read_binary_file(binaryFile);
        cl::Program::Binaries bins{{fileBuf.data(), fileBuf.size()}};
        bool valid_device = false;
        for (unsigned int i = 0; i < devices.size(); i++) {
            auto device = devices[i];
            // Creating Context and Command Queue for selected Device
            OCL_CHECK(err, context = cl::Context(device, nullptr, nullptr, nullptr, &err));
            OCL_CHECK(err, q = cl::CommandQueue(context, device, CL_QUEUE_PROFILING_ENABLE, &err));
            std::cout << "Trying to program device[" << i << "]: " << device.getInfo<CL_DEVICE_NAME>() << std::endl;
            cl::Program program(context, {device}, bins, nullptr, &err);
            if (err != CL_SUCCESS) {
                std::cout << "Failed to program device[" << i << "] with xclbin file!\\n";
            } else {
                std::cout << "Device[" << i << "]: program successful!\\n";
        """
    )
    out_str += format_str(
        f'OCL_CHECK(err, krnl_{top} = cl::Kernel(program, "{top}", &err));', 12, False
    )
    out_str += format_str(
        """            valid_device = true;
            break; // we break because we found a valid device
        }
    }
    if (!valid_device) {
        std::cout << "Failed to program any device found, exit!\\n";
        exit(EXIT_FAILURE);
    }
    """,
        strip=False,
        indent=0,
    )
    out_str += format_str(
        """
        // Allocate Buffer in Global Memory
        // Buffers are allocated using CL_MEM_USE_HOST_PTR for efficient memory and
        // Device-to-host communication
        """
    )
    for i, (in_dtype, in_shape, _, _) in enumerate(inputs):
        out_str += format_str(
            f"OCL_CHECK(err, cl::Buffer buffer_in{i}(context, CL_MEM_USE_HOST_PTR | CL_MEM_READ_ONLY, size_bytes_in{i}, source_in{i}.data(), &err));",
            strip=False,
        )
    for i, (io_type, io_shape, _, _) in enumerate(inputs_outputs):
        out_str += format_str(
            f"OCL_CHECK(err, cl::Buffer buffer_in{i + len(inputs)}(context, CL_MEM_USE_HOST_PTR | CL_MEM_READ_WRITE, size_bytes_out{i}, source_out{i}.data(), &err));",
            strip=False,
        )
    for i in range(len(outputs)):
        final_idx = len(inputs_outputs) + i
        out_str += format_str(
            f"OCL_CHECK(err, cl::Buffer buffer_out{i}(context, CL_MEM_USE_HOST_PTR | CL_MEM_WRITE_ONLY, size_bytes_out{final_idx}, source_out{final_idx}.data(), &err));",
            strip=False,
        )
    # (Golden arrays will be created as part of the golden-reference
    # preparation above so we don't duplicate declarations here.)
    out_str += "\n"
    # Set kernel arguments in the original order of the function signature
    buf_str = ""
    arg_position = 0
    input_buffer_idx = 0
    output_buffer_idx = 0
    input_output_buffer_idx = 0
    
    for arg_type, idx, arg_data in ordered_args:
        if arg_type == 'input':
            dtype, shape, name, kind = arg_data
            if len(shape) == 0:
                # scalar
                out_str += format_str(
                    f"OCL_CHECK(err, err = krnl_{top}.setArg({arg_position}, source_in{input_buffer_idx}));",
                    strip=False,
                )
            else:
                out_str += format_str(
                    f"OCL_CHECK(err, err = krnl_{top}.setArg({arg_position}, buffer_in{input_buffer_idx}));",
                    strip=False,
                )
                buf_str += f"buffer_in{input_buffer_idx}, "
            input_buffer_idx += 1
        elif arg_type == 'output':
            dtype, shape, name, kind = arg_data
            final_idx = len(inputs_outputs) + output_buffer_idx
            out_str += format_str(
                f"OCL_CHECK(err, err = krnl_{top}.setArg({arg_position}, buffer_out{output_buffer_idx}));",
                strip=False,
            )
            output_buffer_idx += 1
        elif arg_type == 'input_output':
            dtype, shape, name, kind = arg_data
            buffer_idx = len(inputs) + input_output_buffer_idx
            out_str += format_str(
                f"OCL_CHECK(err, err = krnl_{top}.setArg({arg_position}, buffer_in{buffer_idx}));",
                strip=False,
            )
            buf_str += f"buffer_in{buffer_idx}, "
            input_output_buffer_idx += 1
        arg_position += 1
    out_str += format_str("// Copy input data to device global memory", strip=False)
    buf_str = buf_str.strip(", ")
    out_str += format_str(
        "OCL_CHECK(err, err = q.enqueueMigrateMemObjects({"
        + buf_str
        + "}, 0 /* 0 means from host*/));",
        strip=False,
    )
    out_str += "\n"
    out_str += format_str(
        """
    cl::Event event;
    uint64_t nstimestart, nstimeend;
    std::cout << "|-------------------------+-------------------------|\\n"
              << "| Kernel                  |    Wall-Clock Time (ns) |\\n"
              << "|-------------------------+-------------------------|\\n";
    """
    )
    out_str += "\n"
    # Launch kernel
    out_str += format_str("// Launch the Kernel", strip=False)
    out_str += format_str(
        f"OCL_CHECK(err, err = q.enqueueTask(krnl_{top}, nullptr, &event));",
        strip=False,
    )
    out_str += "\n"
    out_str += format_str(
        "// Copy Result from Device Global Memory to Host Local Memory",
        strip=False,
    )
    if len(outputs) > 0:
        out_str += format_str(
            "OCL_CHECK(err, err = q.enqueueMigrateMemObjects({"
            + ", ".join([f"buffer_out{i}" for i in range(len(outputs))])
            + "}, CL_MIGRATE_MEM_OBJECT_HOST));",
            strip=False,
        )
    else:
        out_str += format_str(
            "OCL_CHECK(err, err = q.enqueueMigrateMemObjects({"
            + ", ".join([f"buffer_in{len(inputs) - 1}"])
            + "}, CL_MIGRATE_MEM_OBJECT_HOST));",
            strip=False,
        )
    out_str += format_str("q.finish();", strip=False)
    out_str += format_str("// OpenCL Host Code Ends", strip=False)
    out_str += "\n"
    # Timing
    out_str += format_str(
        """
        // Get the execution time
        OCL_CHECK(err, err = event.getProfilingInfo<uint64_t>(CL_PROFILING_COMMAND_START, &nstimestart));
        OCL_CHECK(err, err = event.getProfilingInfo<uint64_t>(CL_PROFILING_COMMAND_END, &nstimeend));
        auto exe_time = nstimeend - nstimestart;
        """
    )
    out_str += "\n"
    out_str += format_str(
        f'std::cout << "| " << std::left << std::setw(24) << "{top} "',
        strip=False,
    )
    out_str += format_str(
        '<< "|" << std::right << std::setw(24) << exe_time << " |\\n";',
        strip=False,
        indent=14,
    )
    out_str += format_str(
        """
        std::cout << "|-------------------------+-------------------------|\\n";
        std::cout << "Note: Wall Clock Time is meaningful for real hardware execution "
                  << "only, not for emulation.\\n";
        std::cout << "Please refer to profile summary for kernel execution time for "
                  << "hardware emulation.\\n";
        std::cout << "Finished execution!\\n\\n";
        """,
    )
    out_str += "\n\n"
    assert len(outputs) <= 1, "Only support one output for now"
    if len(outputs) == 0:
        out_buf = "source_in" + str(len(inputs) - 1)
    else:
        # Use the correct index for outputs (after inputs_outputs)
        final_idx = len(inputs_outputs) + len(outputs) - 1
        out_buf = "source_out" + str(final_idx)
    # If we ran a golden reference on host, compare its output with the
    # kernel output (only support one output for now).
    if golden_ref_found:
        if len(outputs) == 0:
            # nothing to compare
            pass
        else:
            out_str += format_str("// Compare golden reference output with kernel output", strip=False)
            out_str += format_str("{", strip=False)
            out_str += format_str(f"size_t __cmp_size = {out_buf}.size();", strip=False)
            out_str += format_str("if (__cmp_size == 0) { std::cout << \"Warning: empty output for comparison\" << std::endl; }", strip=False)
            out_str += format_str("for (size_t __i = 0; __i < __cmp_size; ++__i) {", strip=False)
            # Compare to golden_out0 which we create as the first golden output
            out_str += format_str("  double __a = (double) "+out_buf+"[__i];", strip=False)
            # If the golden output is a 2D C array emit flattened index mapping
            if len(outputs) > 0 and len(outputs[0][1]) == 2:
                cols = outputs[0][1][1]
                out_str += format_str(f"  double __b = (double) golden_out0[__i/{cols}][__i%{cols}];", strip=False)
            else:
                out_str += format_str("  double __b = (double) golden_out0[__i];", strip=False)
            out_str += format_str("  double __diff = std::abs(__a - __b);", strip=False)
            out_str += format_str("  if (__diff > 1e-3) {", strip=False)
            out_str += format_str("    std::cerr << \"Mismatch at index \" << __i << \" kernel=\" << __a << \" ref=\" << __b << \" diff=\" << __diff << std::endl;", strip=False)
            out_str += format_str("    return EXIT_FAILURE;", strip=False)
            out_str += format_str("  }", strip=False)
            out_str += format_str("}", strip=False)
            out_str += format_str("}", strip=False)
    out_str += format_str(
        f"""    // Write the output data to file
    std::ofstream ofile;
    ofile.open("output.data");
    if (!ofile) {{
        std::cerr << "Failed to open output file!" << std::endl;
        return EXIT_FAILURE;
    }}
    for (unsigned i = 0; i < {out_buf}.size(); i++) {{
        ofile << {out_buf}[i] << std::endl;
    }}
    ofile.close();
    """,
        strip=False,
        indent=0,
    )
    out_str += format_str("return EXIT_SUCCESS;", strip=False)
    out_str += "}\n"
    return out_str


def postprocess_hls_code(hls_code, top=None):
    out_str = ""
    func_decl = False
    has_endif = False
    func_args = []
    for line in hls_code.split("\n"):
        if line == "using namespace std;" or line.startswith("#ifndef"):
            out_str += line + "\n"
            # Add external function declaration
            out_str += '\nextern "C" {\n\n'
        elif line.startswith(f"void {top}"):
            func_decl = True
            out_str += line + "\n"
        elif func_decl and line.startswith(") {"):
            func_decl = False
            out_str += line + "\n"
            # Add extra interfaces
            for i, arg in enumerate(func_args):
                out_str += f"  #pragma HLS interface m_axi port={arg} offset=slave bundle=gmem{i}\n"
        elif func_decl:
            out_str += line + "\n"
            # dtype, var = line.strip().rsplit(" ", 1)
            # comma = "," if var[-1] == "," else ""
            # if "[" in var:  # array
            #     var = var.split("[")[0]
            #     out_str += "  " + dtype + " *" + var + f"{comma}\n"
            #     # only add array to interface
            #     func_args.append(var)
            # else:  # scalar
            #     var = var.split(",")[0]
            #     out_str += "  " + dtype + " " + var + f"{comma}\n"
        elif line.startswith("#endif"):
            out_str += '} // extern "C"\n\n'
            out_str += line + "\n"
            has_endif = True
        else:
            out_str += line + "\n"
    if not has_endif:
        out_str += '} // extern "C"\n'
    return out_str


def generate_description_file(top, src_path, dst_path, frequency):
    with open(src_path, "r", encoding="utf-8") as f:
        desc = f.read()
    desc = desc.replace("top", top)
    desc = json.loads(desc)
    desc["containers"][0]["ldclflags"] += f"  --kernel_frequency {frequency}"
    with open(dst_path, "w", encoding="utf-8") as outfile:
        json.dump(desc, outfile, indent=4)


def update_makefile(file_name, ext_libs):
    with open(file_name, "r", encoding="utf-8") as f:
        makefile = f.read()
    cpp_files = ["kernel.cpp"]
    for lib in ext_libs:
        for impl_path in lib.impls:
            cpp_files.append(impl_path.split("/")[-1])
    makefile = makefile.replace("kernel.cpp", " ".join(cpp_files))
    with open(file_name, "w", encoding="utf-8") as outfile:
        outfile.write(makefile)


def write_tensor_to_file(tensor, shape, file_path):
    with open(file_path, "w", encoding="utf-8") as f:
        if len(shape) == 0:
            # scalar
            f.write(f"{tensor}\n")
        else:
            f.write("\n".join([str(i) for i in tensor.flatten()]))


def read_tensor_from_file(dtype, shape, file_path):
    if dtype == "bf16":
        # numpy does not support bf16
        dtype = "f32"
    arr = np.fromfile(file_path, sep="\n", dtype=np_supported_types[dtype])
    return arr.reshape(shape)


def codegen_csim_host(top, module):
    # Try to find "module_top" first
    func = find_func_in_module(module, "module_top")
    if func is not None:
        top = "module_top"
    else:
        func = find_func_in_module(module, top)
    
    if func is None:
        try:
            mod_text = str(module)
        except Exception:
            mod_text = "<unable to stringify module>"
        raise RuntimeError(f"Function '{top}' not found in module. Module: {mod_text}")
    
    inputs, outputs, inputs_outputs = get_func_inputs_outputs_with_attrs(func)
    
    # Build a mapping to preserve original argument order
    arg_attrs = None
    for attr_p in func.attributes:
        if attr_p.name == "arg_attrs":
            arg_attrs = attr_p.attr
    
    ordered_args = []
    input_idx = 0
    output_idx = 0
    input_output_idx = 0
    
    for i, (arg, arg_attr) in enumerate(zip(func.arguments, arg_attrs)):
        buf_info = arg_attr['buffer.info']
        io = buf_info['io'].value
        if io == 'read-only':
            ordered_args.append(('input', input_idx, inputs[input_idx]))
            input_idx += 1
        elif io == 'write-only':
            ordered_args.append(('output', output_idx, outputs[output_idx]))
            output_idx += 1
        elif io == 'read-write' or io == 'unknown':
            ordered_args.append(('input_output', input_output_idx, inputs_outputs[input_output_idx]))
            input_output_idx += 1
            
    # Start generating the C++ testbench
    out_str = """
#include <iostream>
#include <vector>
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iomanip>

// Declare the kernel function
extern "C" void {top}(
""".format(top=top)

    # Generate kernel function signature
    params = []
    for arg_type, idx, arg_data in ordered_args:
        dtype, shape, name, kind = arg_data
        if dtype in ctype_map:
            ctype = ctype_map[dtype]
        elif dtype.startswith("i") or dtype.startswith("ui"):
            prefix, bitwidth = dtype.split("i")
            new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
            ctype = ctype_map[new_int_type]
        elif dtype.startswith("fixed") or dtype.startswith("ufixed"):
            ctype = "float"
        else:
            raise ValueError(f"Unsupported type: {dtype}")
            
        if len(shape) == 0:
            params.append(f"{ctype} {name}")
        else:
            # Use multi-dimensional array syntax: float A[128][128]
            dims = "".join([f"[{d}]" for d in shape])
            params.append(f"{ctype} {name}{dims}")
            
    out_str += ",\n    ".join(params)
    out_str += ");\n\n"
    
    # Check for golden reference
    golden_ref_paths = ["golden_reference.cpp", os.path.join("src", "golden_reference.cpp")]
    golden_ref_path = None
    for p in golden_ref_paths:
        if os.path.exists(p):
            golden_ref_path = p
            break
    
    golden_ref_found = golden_ref_path is not None
    golden_arg_count = len(ordered_args) # Default to all args

    if golden_ref_found:
        # Parse golden reference to find argument count
        try:
            with open(golden_ref_path, "r") as f:
                content = f.read()
            # Look for top_golden definition
            import re
            match = re.search(r'void\s+top_golden\s*\((.*?)\)', content, re.DOTALL)
            if match:
                args_str = match.group(1)
                if not args_str.strip():
                    golden_arg_count = 0
                else:
                    # Count arguments by splitting by comma, ignoring commas inside brackets/parentheses if any
                    # Simple split by comma should work for standard C declarations unless there are complex types
                    golden_arg_count = len(args_str.split(','))
        except Exception as e:
            logger.warning("Failed to parse golden reference file: %s", e)
            return None

        out_str += '// Declare golden reference function\n'
        out_str += f'extern "C" void top_golden('
        # Use only the first golden_arg_count arguments
        # Re-generate params for golden ref because it might need different types? 
        # Assuming same types for now.
        out_str += ",\n    ".join(params[:golden_arg_count]) 
        out_str += ");\n\n"

    out_str += "int main() {\n"
    out_str += f'    std::cout << "Starting {top} C simulation..." << std::endl;\n\n'
    
    # Allocate memory
    out_str += "    // Allocate memory\n"
    for arg_type, idx, arg_data in ordered_args:
        dtype, shape, name, kind = arg_data
        if dtype in ctype_map:
            ctype = ctype_map[dtype]
        elif dtype.startswith("i") or dtype.startswith("ui"):
            prefix, bitwidth = dtype.split("i")
            new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
            ctype = ctype_map[new_int_type]
        elif dtype.startswith("fixed") or dtype.startswith("ufixed"):
            ctype = "float"
        
        if len(shape) == 0:
            out_str += f"    {ctype} {name};\n"
        else:
            dims = "".join([f"[{d}]" for d in shape])
            out_str += f"    static {ctype} {name}{dims};\n"

    # Re-iterate to create golden buffers
    for i, (arg_type, idx, arg_data) in enumerate(ordered_args):
        dtype, shape, name, kind = arg_data
        if dtype in ctype_map:
            ctype = ctype_map[dtype]
        elif dtype.startswith("i") or dtype.startswith("ui"):
            prefix, bitwidth = dtype.split("i")
            new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
            ctype = ctype_map[new_int_type]
        elif dtype.startswith("fixed") or dtype.startswith("ufixed"):
            ctype = "float"
            
        if golden_ref_found and arg_type == 'output':
             if i < golden_arg_count:
                 dims = "".join([f"[{d}]" for d in shape])
                 out_str += f"    static {ctype} {name}_golden{dims};\n"

    out_str += "\n    // Initialize inputs\n"
    out_str += "    std::srand(42); // Fixed seed for reproducibility\n"
    
    for arg_type, idx, arg_data in ordered_args:
        dtype, shape, name, kind = arg_data
        if arg_type == 'input' or arg_type == 'input_output':
            if len(shape) == 0:
                 out_str += f"    {name} = ({ctype})(std::rand() % 100);\n"
            else:
                # Generate nested loops for initialization
                loop_vars = []
                indent = "    "
                for i, dim in enumerate(shape):
                    loop_var = f"i{i}"
                    loop_vars.append(loop_var)
                    out_str += f"{indent}for (int {loop_var} = 0; {loop_var} < {dim}; {loop_var}++) {{\n"
                    indent += "    "
                
                indices = "".join([f"[{v}]" for v in loop_vars])
                out_str += f"{indent}{name}{indices} = ({ctype})(std::rand() % 100);\n"
                
                # Close loops
                for i in range(len(shape) - 1, -1, -1):
                    indent = indent[:-4]
                    out_str += f"{indent}}}\n"
    
    out_str += "\n    // Run hardware kernel\n"
    out_str += "    std::cout << \"Running hardware kernel...\" << std::endl;\n"
    # Pass arrays directly (decays to pointer to first element, but type matches function sig if declared as array)
    # Wait, if function sig is `float A[128][128]`, passing `A` works.
    args_str = ", ".join([arg_data[2] for _, _, arg_data in ordered_args])
    out_str += f"    {top}({args_str});\n"
    
    if golden_ref_found:
        out_str += "\n    // Run golden reference\n"
        out_str += "    std::cout << \"Running golden reference...\" << std::endl;\n"
        # Construct args for golden ref: inputs are same, outputs use golden buffers
        golden_args = []
        for i, (arg_type, idx, arg_data) in enumerate(ordered_args):
            if i >= golden_arg_count:
                break
            name = arg_data[2]
            if arg_type == 'output':
                golden_args.append(f"{name}_golden")
            else:
                golden_args.append(name)
        golden_args_str = ", ".join(golden_args)
        out_str += f"    top_golden({golden_args_str});\n"
        
        out_str += "\n    // Compare results\n"
        out_str += "    int errors = 0;\n"
        out_str += "    std::cout << \"Comparing results...\" << std::endl;\n"
        
        for i, (arg_type, idx, arg_data) in enumerate(ordered_args):
             if arg_type == 'output':
                if i >= golden_arg_count:
                    continue
                dtype, shape, name, kind = arg_data
                if len(shape) == 0:
                     out_str += f"    if (std::abs({name} - {name}_golden) > 1e-3) errors++;\n"
                else:
                    # Nested loops for comparison
                    loop_vars = []
                    indent = "    "
                    for k, dim in enumerate(shape):
                        loop_var = f"j{k}"
                        loop_vars.append(loop_var)
                        out_str += f"{indent}for (int {loop_var} = 0; {loop_var} < {dim}; {loop_var}++) {{\n"
                        indent += "    "
                    
                    indices = "".join([f"[{v}]" for v in loop_vars])
                    out_str += f"{indent}if (std::abs({name}{indices} - {name}_golden{indices}) > 1e-3) {{\n"
                    out_str += f"{indent}    if (errors < 10) std::cout << \"Mismatch at {name}\" << std::endl;\n"
                    out_str += f"{indent}    errors++;\n"
                    out_str += f"{indent}}}\n"
                    
                    # Close loops
                    for k in range(len(shape) - 1, -1, -1):
                        indent = indent[:-4]
                        out_str += f"{indent}}}\n"

        out_str += "\n    if (errors == 0) {\n"
        out_str += "        std::cout << \"TEST PASSED!\" << std::endl;\n"
        out_str += "        return 0;\n"
        out_str += "    } else {\n"
        out_str += "        std::cout << \"TEST FAILED with \" << errors << \" errors.\" << std::endl;\n"
        out_str += "        return 1;\n"
        out_str += "    }\n"
    else:
        out_str += "\n    std::cout << \"TEST PASSED (No golden reference checked)!\" << std::endl;\n"
        out_str += "    return 0;\n"

    out_str += "}\n"
    return out_str
